+// AC: @ui-app-shell ac-1
+describe("grouped sidebar navigation (@ui-app-shell ac-1)", () => {
+  it("has four navigation groups: Work, Specs, Capture, Config", () => {
+    expect(sidebarSrc).toContain("label: 'Work'");
